def solve(grid):
    if not grid or not grid[0]:
        return 0
    m = len(grid)
    n = len(grid[0])
    visited = [[False]*n for _ in range(m)]
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j]==1 and not visited[i][j]:
                count += 1
                stack=[(i,j)]
                visited[i][j]=True
                while stack:
                    x,y=stack.pop()
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<m and 0<=ny<n and not visited[nx][ny] and grid[nx][ny]==1:
                            visited[nx][ny]=True
                            stack.append((nx,ny))
    return count

