from itertools import groupby

def solve(s):
    return [[c, len(list(g))] for c, g in groupby(s)]

def solve(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for c in reversed(s):
        v = values[c]
        if v < prev:
            total -= v
        else:
            total += v
        prev = v
    return total

def solve(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals)
    result = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= result[-1][1]:
            result[-1][1] = max(result[-1][1], e)
        else:
            result.append([s, e])
    return result

